package com.hellodoc.config;
import com.hellodoc.entity.*; import com.hellodoc.repository.*; import com.hellodoc.service.SpecialtyService; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.ApplicationRunner; import org.springframework.context.annotation.*; import org.springframework.core.annotation.Order; import org.springframework.security.crypto.password.PasswordEncoder; import java.time.LocalTime; import java.util.*;
@Configuration @Profile("dev") public class DemoDoctorSeed {
 @Bean @Order(1) ApplicationRunner seedDemoDoctors(UserRepository users,DoctorApplicationRepository applications,DoctorRepository doctors,AvailabilityRepository availabilities,SpecialtyService specialties,PasswordEncoder encoder,@Value("${HELLODOC_DEMO_PASSWORD:}") String password){return args->{if(password==null||password.length()<12){System.getLogger(getClass().getName()).log(System.Logger.Level.WARNING,"Médecins de démonstration ignorés : configurez HELLODOC_DEMO_PASSWORD (12 caractères minimum) avec le profil dev.");return;}create("demo.cardiologue@hellodoc.local","Nour","Ben Salem","Dr Nour Ben Salem","Cardiologie","Tunis","Avenue Habib Bourguiba","Cardiologue orientée prévention et suivi cardiovasculaire.",users,applications,doctors,availabilities,specialties,encoder,password);create("demo.dentiste@hellodoc.local","Yassine","Trabelsi","Dr Yassine Trabelsi","Odontologie","Sousse","Rue de la République","Chirurgien-dentiste en soins conservateurs et prévention.",users,applications,doctors,availabilities,specialties,encoder,password);};}
 private void create(String email,String first,String last,String title,String specialty,String city,String address,String description,UserRepository users,DoctorApplicationRepository applications,DoctorRepository doctors,AvailabilityRepository availabilities,SpecialtyService specialties,PasswordEncoder encoder,String password){if(users.existsByEmailIgnoreCase(email))return;UserAccount user=users.save(new UserAccount(first,last,email,"+21600000000",address,encoder.encode(password),UserRole.DOCTOR,"ACTIVE"));DoctorApplication app=applications.save(new DoctorApplication(user,title,specialty,"DEMO-"+specialty.toUpperCase(Locale.ROOT),city,address,30,"09:00","16:00",10,"[\"1\",\"2\",\"3\",\"4\",\"5\"]","[{\"name\":\"Consultation\",\"price\":\"60 DT\"}]",description));app.decide("APPROVED","Compte de démonstration local.");Doctor doctor=doctors.save(new Doctor(user,app,title,city,address,address,description,30,10,"[{\"name\":\"Consultation\",\"price\":\"60 DT\"}]"));doctor.addSpecialty(specialties.findOrCreate(specialty));for(int day=1;day<=5;day++)availabilities.save(new Availability(doctor,day,LocalTime.of(9,0),LocalTime.of(16,0),30,10));}
}
